import{_ as d,a0 as l,w as r,s,I as o,x as n,a1 as p,A as a,ao as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"在 VirtualBox 中安裝 Android 系統 | LCTT x X-CMD","titleTemplate":false,"description":"在 VirtualBox 中安裝 Android 系統 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 VirtualBox 中安裝 Android 系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 VirtualBox 中安裝 Android 系統 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180804 Installing Andriod on VirtualBox","title":"在 VirtualBox 中安裝 Android 系統","tag":"201809","desc":""},"relativePath":"201809/20180804 Installing Andriod on VirtualBox.md","filePath":"[post].md"}'),u={name:"201809/20180804 Installing Andriod on VirtualBox.md"};function x(m,t,g,h,A,w){const i=l("Link");return r(),s("div",null,[t[21]||(t[21]=o("h1",{id:"在-virtualbox-中安裝-android-系統",tabindex:"-1"},[n("在 VirtualBox 中安裝 Android 系統 "),o("a",{class:"header-anchor",href:"#在-virtualbox-中安裝-android-系統","aria-label":"Permalink to “在 VirtualBox 中安裝 Android 系統”"},"​")],-1)),t[22]||(t[22]=o("p",null,"如果你正在開發 Android 應用，也許會遇到小麻煩。誠然，ios 移動開發有 macOS 系統平台為其提供友好便利性， Android 開發僅有支持少部分 Android 系統（其中還包括可穿戴設備系統）的 Android Studio 工具。",-1)),t[23]||(t[23]=o("p",null,"毋庸置疑，所有的二進制工具、SDK 工具、開發框架工具以及調試器都會產生大量日誌和其他各種文件，使得你的文件系統很混亂。一個有效的解決方法就是在 VirtualBox 中安裝 Android 系統，這樣還解決了 Android 開發中最為棘手問題之一 —— 設備模擬器。你可以在該虛擬機裏測試應用程序，也可以使用 Android 的內部功能。因此，讓我們迫不及待的開始吧！",-1)),t[24]||(t[24]=o("h3",{id:"準備工作",tabindex:"-1"},[n("準備工作 "),o("a",{class:"header-anchor",href:"#準備工作","aria-label":"Permalink to “準備工作”"},"​")],-1)),o("p",null,[t[1]||(t[1]=n("首先，你需要在你的系統上安裝 VirtualBox，可從",-1)),p(i,{href:"https://www.virtualbox.org/wiki/Downloads"},{default:a(()=>[...t[0]||(t[0]=[n("這裏",-1)])]),_:1}),t[2]||(t[2]=n("下載 Windows 版本、macOS 版本或者各種 Linux 版本的 VitualBox。然後，你需要一個能在 x86 平台運行的 Android 鏡像，因為 VirtualBox 為虛擬機提供運行 x86 或者 x86_64（即 AMD64）平台的功能。",-1))]),o("p",null,[t[4]||(t[4]=n("雖然大部分 Android 設備都在 ARM 上運行，但我們依然可以從 ",-1)),p(i,{href:"http://www.android-x86.org/"},{default:a(()=>[...t[3]||(t[3]=[n("Android on x86 項目",-1)])]),_:1}),t[5]||(t[5]=n(" 中獲得幫助。這些優秀的開發者已經將 Android 移植到 x86 平台上運行（包括實體機和虛擬機），我們可以下載最新版本的 Android 7.1。你也可以用之前更為穩定的版本，本文寫作時最新穩定版是 Android 6.0。",-1))]),t[25]||(t[25]=e('<h3 id="創建-vm-虛擬機" tabindex="-1">創建 VM 虛擬機 <a class="header-anchor" href="#創建-vm-虛擬機" aria-label="Permalink to “創建 VM 虛擬機”">​</a></h3><p>打開 VirtualBox，單擊左上角的 “新建” 按鈕，在彈出的窗口中選擇 “類型：Linux” ，然後根據下載的 ISO 鏡像來確定版本，x86 對應 “32-bit”，x86_64 對應 “64-bit”，此處選擇 “Linux 2.6 / 3.x / 4.x (64-bit)”。</p><p>RAM 大小設置為 2 GB 到你係統能提供的最大內存之間。如果你想模擬真實的使用環境你可以設置 6 GB RAM 和 32 GB ROM。</p><p><img src="https://linuxhint.com/wp-content/uploads/2018/08/a.png" alt=""></p><p><img src="https://linuxhint.com/wp-content/uploads/2018/08/a1.png" alt=""></p><p>創建完成後，你還需要做一些設置，添加更多的處理器核心，提高開機顯示內存。在 VM 上打開設置選項，“設置 -&gt; 系統 -&gt; 處理器”，如果硬件條件允許，可以多分配一些處理器。</p><p><img src="https://linuxhint.com/wp-content/uploads/2018/08/a2.png" alt=""></p><p>在 “設置 -&gt; 顯示 -&gt; 顯存大小” 中，你可以分配一大塊內存並開啓 3D 加速功能。</p><p><img src="https://linuxhint.com/wp-content/uploads/2018/08/a3.png" alt=""></p><p>現在我們可以啓動 VM 虛擬機了。</p><h3 id="安裝-android" tabindex="-1">安裝 Android <a class="header-anchor" href="#安裝-android" aria-label="Permalink to “安裝 Android”">​</a></h3><p>首次啓動 VM 虛擬機，VirtualBox 會提示你需要提供啓動媒介，選擇之前下載好的Android 鏡像。</p><p><img src="https://linuxhint.com/wp-content/uploads/2018/08/a4.png" alt=""></p><p>下一步，如果想長時間使用 Android，選擇 “Installation” 選項，你也可以選擇 Live 模式體驗 Android 環境。</p><p><img src="https://linuxhint.com/wp-content/uploads/2018/08/a5.png" alt=""></p><p>按回車鍵。</p><h4 id="分區" tabindex="-1">分區 <a class="header-anchor" href="#分區" aria-label="Permalink to “分區”">​</a></h4><p>分區是通過文本界面操作，並沒有友好的 GUI 界面，所以每個操作都需要小心對待。例如，在第一屏中還沒有創建分區並且只檢測到原始（虛擬）硬盤時顯示如下。</p><p><img src="https://linuxhint.com/wp-content/uploads/2018/08/a6.png" alt=""></p><p>紅色字母 <code>C</code> 和 <code>D</code> 表明 <code>C</code> 開頭選項可以創建或者修改分區，<code>D</code> 開頭選項可以檢測設備。你可以選擇 <code>D</code> 開頭選項，然後它就會檢測硬盤，也可不進行這步操作，因為在啓動的時候它會自動檢測。</p><p>我們選擇 <code>C</code> 開頭選項，在虛擬盤中創建分區。官方不推薦使用 GPT 格式，所以我們選擇 “No” 並按回車鍵。</p><p><img src="https://linuxhint.com/wp-content/uploads/2018/08/a7.png" alt=""></p><p>現在你被引導到 fdisk 工具頁面。</p><p><img src="https://linuxhint.com/wp-content/uploads/2018/08/a8.png" alt=""></p><p>為了簡潔起見，我們就只創建一個較大的分區，使用方向鍵來選擇 “New” ，然後選擇 “Primary”，按回車鍵以確認。</p><p><img src="https://linuxhint.com/wp-content/uploads/2018/08/a9.png" alt=""></p><p>分區大小系統已經為你計算好了，按回車鍵確認。</p><p><img src="https://linuxhint.com/wp-content/uploads/2018/08/a10.png" alt=""></p><p>這個分區就是 Android 系統所在的分區，所以需要它是可啓動的。選擇 “Bootable”，然後按回車鍵（上方表格中 “Flags” 標誌下面會出現 “boot” 標誌），進一步，選擇 “Write” 選項，保存剛才的操作記錄並寫入分區表。</p><p><img src="https://linuxhint.com/wp-content/uploads/2018/08/a11.png" alt=""></p><p>現在你可以選擇退出分區工具，然後繼續安裝過程。</p><p><img src="https://linuxhint.com/wp-content/uploads/2018/08/a12.png" alt=""></p><h4 id="文件系統格式化為-ext4-並安裝-android" tabindex="-1">文件系統格式化為 EXT4 並安裝 Android <a class="header-anchor" href="#文件系統格式化為-ext4-並安裝-android" aria-label="Permalink to “文件系統格式化為 EXT4 並安裝 Android”">​</a></h4><p>在“Choose Partition”分區頁面上會出現一個剛剛我們創建的分區，選擇它並點擊“OK”進入。</p><p><img src="https://linuxhint.com/wp-content/uploads/2018/08/a13.png" alt=""></p><p>在下一個菜單中選擇 Ext4 作為實際的文件系統，在下一頁中選擇 “Yes” 然後格式化開始。會提示是否安裝 GRUB 引導工具以及是否允許在目錄 <code>/system</code> 進行讀寫，都選擇 “Yes” 。現在，安裝進程開始。</p><p>安裝完成後，當系統提示可以重啓的時候你可以安全地重啓系統。在重啓之前，你可以先關機，然後在 VitualBox 的 “設置 -&gt; 存儲” 中檢查 Android iso 鏡像是否還連接在虛擬機上，如果在，將它移除。</p><p><img src="https://linuxhint.com/wp-content/uploads/2018/08/a14.png" alt=""></p><p>移除安裝媒介並保存修改，再去啓動 VM 虛擬機。</p><h4 id="運行-android" tabindex="-1">運行 Android <a class="header-anchor" href="#運行-android" aria-label="Permalink to “運行 Android”">​</a></h4><p>在 GRUB 引導界面，有調試模式和普通模式的選項。我們選擇默認選項，如下圖所示。</p><p><img src="https://linuxhint.com/wp-content/uploads/2018/08/a16.png" alt=""></p><p>如果一切正常，你將會看到如下界面：</p><p><img src="https://linuxhint.com/wp-content/uploads/2018/08/a17.png" alt=""></p><p>如今的 Android 系統使用觸摸交互而不是鼠標。不過 Android-x86 平台提供了鼠標操作支持，但開始時可能需要方向鍵來輔助操作。</p><p><img src="https://linuxhint.com/wp-content/uploads/2018/08/a18.png" alt=""></p><p>移動到”let’s go“按鈕並按下回車鍵。選擇 “Set up as new” 選項，回車確認。</p><p><img src="https://linuxhint.com/wp-content/uploads/2018/08/a19.png" alt=""></p><p>在提示用谷歌賬户登陸之前，系統檢查更新並檢測設備信息。你可以跳過這一步，直接去設置日期和時間、用户名等。</p><p>還有一些其他的選項，和讓你設置一個新的 Android 設備類似。選擇 “I Agree” 選項同意有關更新、服務等的相應的選項，當然谷歌的服務條款是不得不同意的。</p><p><img src="https://linuxhint.com/wp-content/uploads/2018/08/a20.png" alt=""></p><p>在這之後，因為它是個虛擬機，所以可能需要添加額外的 email 賬户來設置 “On-body detection”，大部分的選項對我們來説都沒有多大作用，因此可以選擇 ”All Set“。</p><p>接下來，它會提示你選擇主屏應用，這個根據個人需求選擇。現在我們進入了一個虛擬的 Android 系統。</p><p><img src="https://linuxhint.com/wp-content/uploads/2018/08/a21.png" alt=""></p><p>如果你需要在 VM 做一些交互測試，有個可觸摸屏幕會提供很大的方便，因為那樣才更接近真實使用環境。</p><p>希望這篇教程會給你帶來幫助。</p><hr>',57)),o("p",null,[t[7]||(t[7]=n("via: ",-1)),p(i,{href:"https://linuxhint.com/install_android_virtualbox/"},{default:a(()=>[...t[6]||(t[6]=[n("https://linuxhint.com/install_android_virtualbox/",-1)])]),_:1})]),o("p",null,[t[12]||(t[12]=n("作者：",-1)),p(i,{href:"https://linuxhint.com/author/sranvir155/"},{default:a(()=>[...t[8]||(t[8]=[n("Ranvir Singh",-1)])]),_:1}),t[13]||(t[13]=n(" 選題：",-1)),p(i,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[9]||(t[9]=[n("lujun9972",-1)])]),_:1}),t[14]||(t[14]=n(" 譯者：",-1)),p(i,{href:"https://github.com/jrglinux"},{default:a(()=>[...t[10]||(t[10]=[n("jrglinux",-1)])]),_:1}),t[15]||(t[15]=n(" 校對：",-1)),p(i,{href:"https://github.com/wxy"},{default:a(()=>[...t[11]||(t[11]=[n("wxy",-1)])]),_:1})]),o("p",null,[t[18]||(t[18]=n("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[16]||(t[16]=[n("LCTT",-1)])]),_:1}),t[19]||(t[19]=n(" 原創編譯，",-1)),p(i,{href:"https://linux.cn/"},{default:a(()=>[...t[17]||(t[17]=[n("Linux中國",-1)])]),_:1}),t[20]||(t[20]=n(" 榮譽推出",-1))])])}const B=d(u,[["render",x]]);export{b as __pageData,B as default};
